# Collect all ${...} references in the whole file text.
refs = sorted(set(re.findall(r"\$\{([^}]+)\}", p.read_text(encoding="utf-8"))))

def resolve(ref):
    cur = ns
    for part in ref.split("."):
        if isinstance(cur, dict) and part in cur:
            cur = cur[part]
        else:
            return False
    return True

missing = [r for r in refs if not resolve(r)]
